def uniqueSupersequence(nums, sequences):
    n = len(nums)
    adj = [set() for _ in range(n + 1)]
    indeg = [0] * (n + 1)
    for s in sequences:
        for a, b in zip(s, s[1:]):
            if b not in adj[a]:
                adj[a].add(b)
                indeg[b] += 1
    ready = [v for v in range(1, n + 1) if indeg[v] == 0]
    i = 0
    while ready:
        if len(ready) > 1:
            return False
        u = ready[0]
        if nums[i] != u:
            return False
        i += 1
        ready = []
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                ready.append(v)
    return i == n
